/* 双轨打分：基本面 60 + 价格 40。价格折价分 <10（溢价超过 score_block_pct，默认 10%）不买；
   总分须 > score_min（默认 70）。现价高于目标价但不超过 score_half_pct（默认 5%）只建半仓。
   治理枚举没有「中央/地方」分档：state 按地方国企 8 分；central 留给以后补字段。
   行业 ocfdMin<=0（银行）OCF 不参与否决，该项给满分，避免缺口径把银行打到 70 分以下。 */
function planScore(r) {
  const half = +RULES.score_half_pct || 5;
  const block = +RULES.score_block_pct || 10;
  const minTotal = +RULES.score_min || 70;
  const yld = r.yldNow != null ? +r.yldNow : (r.t && r.t.yld != null ? +r.t.yld : null);
  let yldPts = 0;
  if (yld != null && isFinite(yld)) {
    if (yld > 5) yldPts = 20;
    else if (yld >= 4) yldPts = 15;
    else if (yld >= 3) yldPts = 10;
  }
  let ocfPts = 0;
  const ocfdMin = r.t ? _mThresh('ocfdMin', +RULES.ocf_min || 1, r.t) : (+RULES.ocf_min || 1);
  if (!(ocfdMin > 0)) ocfPts = 15;
  else {
    let ocf = null;
    if (r.t && has2y(r.t.ocfd2y)) {
      const v = r.t.ocfd2y;
      ocf = Array.isArray(v) ? Math.min(+v[0], +v[1]) : +v;
    } else if (r.t && r.t.ocfd != null) ocf = +r.t.ocfd;
    if (ocf != null && isFinite(ocf)) {
      if (ocf > 2) ocfPts = 15;
      else if (ocf >= 1) ocfPts = 10;
    }
  }
  const vol = r.t && r.t.vol != null ? +r.t.vol : null;
  let volPts = 0;
  if (vol != null && isFinite(vol)) {
    if (vol < 18) volPts = 15;
    else if (vol <= 22) volPts = 10;
    else if (vol <= 25) volPts = 5;
  }
  const g = r.t && r.t.governance;
  let govPts = 0;
  if (g === 'central') govPts = 10;
  else if (g === 'state') govPts = 8;
  else if (g === 'none') govPts = 4;
  const fund = yldPts + ocfPts + volPts + govPts;
  let pxPts = 0, sizeFrac = 0, premium = null;
  if (r.buyToTgtPct != null && isFinite(r.buyToTgtPct)) {
    premium = -r.buyToTgtPct;
    if (premium <= 0) { pxPts = 25; sizeFrac = 1; }
    else if (premium <= half) { pxPts = 15; sizeFrac = 0.5; }
    else if (premium <= block) { pxPts = 5; sizeFrac = 0; }
  }
  let pctPts = 0;
  const yp = r.margin && r.margin.yldPct;
  if (yp != null && !r.pctSampleLow && isFinite(+yp)) {
    if (+yp >= 80) pctPts = 15;
    else if (+yp >= 60) pctPts = 10;
    else if (+yp >= 40) pctPts = 5;
  }
  const price = pxPts + pctPts;
  const total = fund + price;
  return {
    yldPts: yldPts, ocfPts: ocfPts, volPts: volPts, govPts: govPts, fund: fund,
    pxPts: pxPts, pctPts: pctPts, price: price, total: total,
    sizeFrac: sizeFrac, premium: premium, minTotal: minTotal,
    buyable: pxPts >= 10 && total > minTotal
  };
}

function buildPlan(amount, rows, T) {

tool_input.old_string:
// 硬门槛：有安全边际数据时，必须达股息率目标价（一票否决）；分位/布林带只作加分。
if (hasMargin && r.margin) {
  if (!r.marginBuy) {
    const why = [];
    if (r.buyToTgtPct != null && r.buyToTgtPct < 0) why.push('距目标价还差 ' + fmt(-r.buyToTgtPct, 1) + '%');
    if (r.margin.yldPct != null) why.push('分位 ' + fmt(r.margin.yldPct, 0));
    skipped.push({ r: r, why: '未达股息率目标价（' + (why.join('，') || '指标未触发') + '）' });
    return;
  }
} else {
  // 该只缺指标（整体比例已 <2/3，否则上面已整体降级返回）：只跳过这一只
  skipped.push({ r: r, why: '该标的缺安全边际指标' });
  return;
}

tool_input.new_string:
// 缺指标仍跳过这一只（整体比例已 <2/3，否则上面已整体降级返回）。
// 不再用 marginBuy 一票否决：溢价过大或总分不够才跳过，0~5% 溢价允许半仓。
if (!(hasMargin && r.margin)) {
  skipped.push({ r: r, why: '该标的缺安全边际指标' });
  return;
}
const sc = planScore(r);
r.planScore = sc;
if (sc.pxPts < 10) {
  const gap = sc.premium != null ? '溢价 ' + fmt(Math.max(0, sc.premium), 1) + '%' : '无目标价';
  skipped.push({ r: r, why: '价格分 ' + sc.pxPts + '（' + gap + '，溢价超过 ' + (+RULES.score_half_pct || 5) + '% 不买），总分 ' + sc.total });
  return;
}
if (!(sc.total > sc.minTotal)) {
  skipped.push({ r: r, why: '总分 ' + sc.total + ' ≤ ' + sc.minTotal + '（基本面 ' + sc.fund + ' + 价格 ' + sc.price + '）' });
  return;
}

tool_input.old_string:
// 排序：股息率达标者中，安全边际强度优先，再按「现价低于目标价越多越优先」，最后 vwap 折价
cands.sort((a, b) =>
  (b.marginStrength || 0) - (a.marginStrength || 0) ||
  ((b.buyToTgtPct || 0) - (a.buyToTgtPct || 0)) ||
  ((b.disc || 0) - (a.disc || 0)));

const plannedCount = Math.max(1, Math.min(maxBuys, cands.length));
const equalAmt = amount / plannedCount;
const hardCap = Math.min(capRoom, indRoom, mktRoom, poolLeft);
let want = Math.min(equalAmt, hardCap);
// ④ 不够单笔下限时：若额度仍有空间，抬到 min_ticket（避免被最低佣金吃掉）；否则直接跳过
if (want < minTicket) {
  if (hardCap >= minTicket) want = minTicket;
  else { skipped.push({ r: r, why: '额度不足单笔下限（可用 ' + fmt(Math.max(0, hardCap), 0) + ' 元 < ' + fmt(minTicket, 0) + '）' }); return; }
}

tool_input.new_string:
const plannedCount = Math.max(1, Math.min(maxBuys, cands.length));
const equalAmt = amount / plannedCount;
const hardCap = Math.min(capRoom, indRoom, mktRoom, poolLeft);
const frac = (r.planScore && r.planScore.sizeFrac > 0 && r.planScore.sizeFrac < 1) ? r.planScore.sizeFrac : 1;
let want = Math.min(equalAmt * frac, hardCap);
// ④ 满仓不不单笔下限时抬到 min_ticket；半仓不抬，避免把「提前建仓」又买成满仓
if (want < minTicket) {
  if (frac >= 1 && hardCap >= minTicket) want = minTicket;
  else {
    skipped.push({ r: r, why: (frac < 1 ? '提前建仓（半仓）' : '额度') + '不足单笔下限（可用 ' + fmt(Math.max(0, want), 0) + ' 元 < ' + fmt(minTicket, 0) + '）' });
    return;
  }
}

